function openInfoModal(title,items,options={}){document.querySelector('.info-modal-backdrop')?.remove();const back=node('div','info-modal-backdrop');const dialog=node('section','info-modal '+(options.tone||''));dialog.setAttribute('role','dialog');dialog.setAttribute('aria-modal','true');dialog.setAttribute('aria-labelledby','info-modal-title');const head=node('div','info-modal-head');const badge=node('span','info-modal-icon');badge.append(icon(options.icon||'info'));const titleWrap=node('div');titleWrap.append(node('p','eyebrow',options.kicker||'HƯỚNG DẪN NHANH'),node('h2','info-modal-title',title));const close=button('Đóng',()=>back.remove(),'icon-close','x');close.setAttribute('aria-label','Đóng hướng dẫn');head.append(badge,titleWrap,close);const body=node('div','info-modal-body');items.forEach(item=>{if(Array.isArray(item)){const grid=node('div','modal-grid');item.forEach(x=>{const card=node('article','modal-note');card.append(node('b','',x.title),node('p','',x.text));grid.append(card);});body.append(grid);}else body.append(node('p','',item));});dialog.append(head,body);back.append(dialog);back.addEventListener('click',e=>{if(e.target===back)back.remove();});document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){back.remove();document.removeEventListener('keydown',esc);}});document.body.append(back);close.focus();}
function ipaGuideItems(){return [[{title:'01 · Nghe chậm',text:'Bấm loa từ/cụm, nhìn IPA và bắt âm nhấn chính trước.'},{title:'02 · Nhắc lại',text:'Nói thành tiếng 2 lần. Lần hai nói nhanh hơn một chút.'},{title:'03 · Đổi thông tin',text:'Dùng câu mẫu nhưng thay tên, nơi chốn hoặc ý của bạn.'},{title:'04 · Ôn lại',text:'Gặp lại từ sau 1, 3 và 7 ngày để nhớ lâu hơn.'}],[{title:'/θ/ và /ð/',text:'Đầu lưỡi nhẹ giữa hai hàm răng. /θ/ không rung cổ, /ð/ có rung cổ.'},{title:'/ɪ/ và /iː/',text:'/ɪ/ ngắn, thả lỏng. /iː/ dài hơn, miệng kéo nhẹ.'},{title:'/æ/ và /ə/',text:'/æ/ mở miệng rộng. /ə/ rất nhẹ, gần âm “ơ”.'},{title:'/ʃ/ và /tʃ/',text:'/ʃ/ thổi hơi liên tục. /tʃ/ chặn rồi bật hơi.'},{title:'/r/, /ɝ/, /ɚ/',text:'Giọng Mỹ: đầu lưỡi không chạm vòm, âm r gọn trong miệng.'},{title:'/ŋ/',text:'Gần “ng” tiếng Việt trong sing. Không tự thêm /g/ cuối từ.'}],'Mẹo nhanh: dấu /ˈ/ đứng ngay trước âm tiết nhấn chính. Khi nói câu, ưu tiên nhấn từ mang ý chính.','Loa không phát? Thử đổi giọng đọc, kiểm tra âm lượng hoặc mở bằng trình duyệt hệ thống.'];}
let toastTimer=null;function toast(message){const el=$('toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2200);}
function save(){state.meta??={updatedAt:0};state.meta.updatedAt=Date.now();try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageOkay=true;}catch{storageOkay=false;}ProgressSync.queue(state);storageNotice();}
function storageNotice(){const remote=ProgressSync.getStatus();$('storage-status').textContent=!storageOkay?'Không thể lưu bản tạm trên thiết bị. '+remote.message:remote.message;}
function clearSpeaking(){document.querySelectorAll('.speaking').forEach(x=>x.classList.remove('speaking'));}
function stop(){active=null;if(synth)synth.cancel();clearSpeaking();$('stop')?.classList.remove('is-speaking');$('audio-status').textContent='Bấm nút nghe để phát âm. Chọn tốc độ chậm nếu cần.';}
function loadVoices(){if(!synth)return;const old=$('voice').value;voices=synth.getVoices().filter(v=>/^en([-_]|$)/i.test(v.lang));voices.sort((a,b)=>Number(/^en[-_]US/i.test(b.lang))-Number(/^en[-_]US/i.test(a.lang)));$('voice').replaceChildren();if(!voices.length){$('voice').add(new Option('Tiếng Anh Mỹ · giọng thiết bị','default'));return;}voices.forEach(v=>$('voice').add(new Option(v.name+' · '+v.lang,v.voiceURI)));if(voices.some(v=>v.voiceURI===old))$('voice').value=old;}
function say(text,{hidden=false,onEnd=null,wordId=null}={}){
 if(!synth){$('audio-status').textContent='Trình duyệt chưa hỗ trợ loa. Hãy mở bằng trình duyệt có giọng tiếng Anh.';return;}
 stop();const u=new SpeechSynthesisUtterance(text);active=u;u.lang='en-US';u.rate=Number($('rate').value);const v=voices.find(v=>v.voiceURI===$('voice').value);if(v){u.voice=v;u.lang=v.lang;}
 u.onstart=()=>{if(active!==u)return;$('stop')?.classList.add('is-speaking');$('audio-status').textContent=hidden?'Đang phát câu hỏi nghe…':'Đang đọc: '+text;if(wordId&&!hidden)document.querySelector('[data-entry="'+wordId+'"]')?.classList.add('speaking');};
 u.onend=()=>{if(active!==u)return;active=null;clearSpeaking();$('stop')?.classList.remove('is-speaking');$('audio-status').textContent=hidden?'Đã phát xong. Chọn nghĩa bạn nghe được.':'Đã đọc xong. Hãy nhắc lại bằng giọng của bạn.';onEnd?.();};
 u.onerror=e=>{if(active!==u)return;active=null;clearSpeaking();$('stop')?.classList.remove('is-speaking');if(['canceled','interrupted'].includes(e.error))return;$('audio-status').textContent='Chưa phát được âm thanh. Thử giọng khác hoặc trình duyệt hệ thống. Trong bài kiểm tra, bạn có thể bỏ qua câu nghe; câu bỏ qua không được tính đúng.';};
 $('audio-status').textContent='Đang chuẩn bị giọng đọc…';synth.speak(u);
}
function speak(w,ex=false){say(ex?w.example:w.word,{wordId:w.id});}
function topicWords(){return WORDS.filter(w=>w.group===selected);}
function allProgress(){const now=Date.now(),learned=WORDS.filter(w=>state.records[w.id]?.seen>0).length,completed=GROUPS.filter((_,g)=>topicStatus(g).complete).length,due=WORDS.filter(w=>state.records[w.id]?.due<=now).length,score=learned*10+state.history.filter(h=>h.percent>=80).length*50,days=[...new Set(state.history.map(h=>new Date(h.at).toDateString()))].length;return {learned,completed,due,score,days,percent:Math.round(learned/TOTAL_TARGET*100),catalogPercent:Math.round(learned/WORDS.length*100)};}
function renderHeaderStats(){const actions=document.querySelector('.header-actions');if(!actions)return;let stats=actions.querySelector('.top-stats');if(!stats){stats=node('div','top-stats');actions.prepend(stats);}const s=allProgress();stats.replaceChildren();for(const [value,label,cls] of [[s.days||0,'ngày học','streak'],[s.score.toLocaleString('vi-VN'),'điểm','xp'],[s.catalogPercent+'%','3.000 hiện có','ring']]){const item=node('span','top-stat '+cls);item.append(node('b','',String(value)),node('small','',label));stats.append(item);}}
function progress(){const words=topicWords(),total=words.length,done=words.filter(w=>state.records[w.id]?.seen>0).length,due=engine.reviewQueue(state.records,selected).length,last=[...state.history].reverse().find(h=>h.group===selected&&h.mode==='test'),percent=Math.round(done/Math.max(1,total)*100);const box=$('progress-summary');box.replaceChildren();const overview=node('section','progress-overview');const ring=node('div','mini-ring');ring.style.setProperty('--value',percent);ring.append(node('b','',percent+'%'));const main=node('div','progress-main');main.append(node('b','',done+'/'+total),node('span','','mục đã luyện trong bài này'));const meta=node('div','progress-meta');for(const [value,label,cls] of [[due,'đến hạn ôn trong bài này','due'],[last?last.percent+'%':'Chưa làm','test gần nhất của bài này','last']]){const item=node('div','progress-stat '+cls);item.append(node('b','',String(value)),node('span','',label));meta.append(item);}overview.append(ring,main,meta);box.append(overview);}
function topicStatus(group){const learned=WORDS.filter(w=>w.group===group&&state.records[w.id]?.seen>0).length;const image=state.skills?.[group]?.imagePassed===true;const situation=state.skills?.[group]?.situationPassed===true;const quiz=state.history.some(h=>h.group===group&&h.mode==='quiz'&&h.percent>=80);const test=state.history.some(h=>h.group===group&&h.mode==='test'&&h.passed);return {learned,image,situation,quiz,test,complete:learned>=topicTotal(group)&&image&&situation&&quiz&&test};}
function updateCompletion(group){state.completions??={};const status=topicStatus(group);if(status.complete&&!state.completions[group])state.completions[group]=Date.now();return status;}
function refreshTopicMarkers(){document.querySelectorAll('#topics button').forEach((b,i)=>{let mark=b.querySelector('.topic-check'),meter=b.querySelector('.topic-meter');if(!mark){mark=node('span','topic-check');b.append(mark);}if(!meter){meter=node('span','topic-meter');meter.append(node('i'));b.append(meter);}const status=topicStatus(i),done=!!state.completions?.[i],percent=Math.min(100,topicStepPercent(status,i));mark.textContent=done?'✓':'';mark.setAttribute('aria-label',done?'Đã hoàn thành':'Chưa hoàn thành');meter.firstChild.style.width=percent+'%';b.classList.toggle('topic-success',done);});Array.from($('topic-select').children).forEach((o,i)=>{o.textContent=(state.completions?.[i]?'✓ ':'')+String(i+1).padStart(2,'0')+' · '+GROUPS[i];});}
