function wordTokens(text){return String(text).replace(/I'm/gi,'I am').replace(/you're/gi,'you are').replace(/I'd/gi,'I would').replace(/[^a-zA-Z ]/g,' ').split(/\s+/).map(x=>x.toLowerCase()).filter(x=>x.length>2&&!['the','you','your','with','for','and','are','this','that','have','what','how','can','could','would','please','good','nice','want','need','from','about','into','onto','there','here'].includes(x)).slice(0,3);}
function visualQuery(w){const hay=w.word+' '+w.meaning+' '+w.example,found=visualRules.find(([re])=>re.test(hay));if(found)return found[3];const base=wordTokens(w.word);return [...base,groupVisualQuery[w.group]||'english vocabulary object'].join(' ').trim();}
function imageUrl(provider,query,w){const q=encodeURIComponent(query);return provider==='unsplash'?'https://source.unsplash.com/featured/640x480/?'+q:'https://loremflickr.com/640/480/'+q+'?lock='+(10000+w.id);}
function visualForWord(w){const hay=(w.word+' '+w.meaning+' '+w.example);const found=visualRules.find(([re])=>re.test(hay));const [fallback,theme]=visualFallback[w.group]||['✨','talk'];const query=visualQuery(w);return {emoji:found?found[1]:fallback,theme:found?found[2]:theme,label:w.word,query,url:imageUrl('unsplash',query,w),fallbackUrl:imageUrl('lorem',query,w)};}
function visualTile(w,large=false,hideLabel=false){const v=visualForWord(w),wrap=node('div','word-visual '+v.theme+(large?' large':'')+(hideLabel?' recall-image':''));wrap.setAttribute('role','img');wrap.setAttribute('aria-label',hideLabel?'Ảnh gợi nhớ từ vựng. Hãy đoán trước khi mở đáp án.':'Ảnh public minh họa cho '+w.word+': '+w.meaning);wrap.title='Ảnh tìm theo: '+v.query;const img=document.createElement('img');img.src=v.url;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{if(img.dataset.fallback!=='1'){img.dataset.fallback='1';img.src=v.fallbackUrl;return;}wrap.classList.add('image-failed');};wrap.append(img,node('span','visual-glow'),node('span','visual-emoji',v.emoji),node('span','visual-label',w.word));return wrap;}
function leaveSession(){if(session&&!session.finished){if(!window.confirm('Rời bài đang làm? Quiz đã trả lời được lưu; bài test chưa nộp sẽ không được lưu.'))return false;}session=null;stop();return true;}
