function feedbackFor(q){if(q.wordId){const w=engine.byId.get(q.wordId);return w.word+' = '+w.meaning+'. Ví dụ: '+w.example;}return q.type==='image'?SCENES[q.group].caption+' — '+SCENES[q.group].vi:SCENES[q.group].why;}
function submitAnswer(value,skipped=false){const s=session;if(!s||s.locked||s.finished)return;const q=s.questions[s.index];if(q.type==='listen'&&!s.heard&&!skipped)return;s.locked=true;stop();const answer={value,skipped,correct:engine.grade(q,value,skipped)};s.answers.push(answer);if(s.mode!=='test'){recordAnswer(q,answer.correct);save();render();}else nextQuestion();}
function nextQuestion(){const s=session;if(!s)return;stop();if(s.index+1===s.questions.length){finishSession();return;}s.index++;s.locked=false;s.heard=false;render();}
function finishSession(){const s=session;if(s.finished)return;const sum=engine.summary(s.questions,s.answers);if(s.mode==='test')s.questions.forEach((q,i)=>recordAnswer(q,s.answers[i].correct));state.history.push({group:s.group,mode:s.mode,at:Date.now(),percent:sum.percent,passed:s.mode==='test'&&sum.passed});state.history=state.history.slice(-500);s.finished=true;s.summary=sum;updateCompletion(s.group);save();render();}
